// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/model-listings", wrapper.ListAdminModelListings)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/model-listings", wrapper.CreateAdminModelListing)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/model-listings/{model_listing_id}", wrapper.DeleteAdminModelListing)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/model-listings/{model_listing_id}", wrapper.GetAdminModelListing)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/model-listings/{model_listing_id}", wrapper.UpdateAdminModelListing)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/models", wrapper.ListAdminModels)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/models", wrapper.CreateAdminModel)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/models/{model_id}", wrapper.DeleteAdminModel)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/models/{model_id}", wrapper.GetAdminModel)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/models/{model_id}", wrapper.UpdateAdminModel)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/models/{model_id}/customer-prices", wrapper.GetAdminModelCustomerPrices)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/models/{model_id}/customer-prices", wrapper.ReplaceAdminModelCustomerPrices)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/provider-keys", wrapper.ListAdminProviderKeys)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/provider-keys", wrapper.CreateAdminProviderKey)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/provider-keys/{provider_key_id}", wrapper.DeleteAdminProviderKey)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/provider-keys/{provider_key_id}", wrapper.GetAdminProviderKey)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/provider-keys/{provider_key_id}", wrapper.UpdateAdminProviderKey)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/provider-keys/{provider_key_id}/prices", wrapper.GetAdminProviderKeyPrices)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/provider-keys/{provider_key_id}/prices", wrapper.ReplaceAdminProviderKeyPrices)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/provider-keys/{provider_key_id}/rotate-secret", wrapper.RotateAdminProviderKeySecret)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/providers", wrapper.ListAdminProviders)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/providers", wrapper.CreateAdminProvider)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/providers/{provider_id}", wrapper.DeleteAdminProvider)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/providers/{provider_id}", wrapper.GetAdminProvider)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/providers/{provider_id}", wrapper.UpdateAdminProvider)

	return m
}

